import java.util.*;

public class Main {
    static class Edge {
        int v, w, c, nx;
        public Edge(int v, int w, int c, int nx) {
            this.v = v;
            this.w = w;
            this.c = c;
            this.nx = nx;
        }
    }

    static final int oo = 2139063143;
    static int N = 5010000;
    static int P = 1000000007;
    static double eps = 1e-7;

    static List<Edge> edgeList = new ArrayList<>();
    static int[] headList;
    static int edgeCount;
    static int source, sink;
    static int[] dist, flow, pre, las;
    static boolean[] in_q;

    static boolean bellmanFord(int sink) {
        int n = sink;
        for (int i = 1; i <= n; i++) {
            dist[i] = Integer.MAX_VALUE;
            flow[i] = 0;
            pre[i] = 0;
            las[i] = 0;
            in_q[i] = false;
        }
        Queue<Integer> q = new LinkedList<>();
        dist[source] = 0;
        flow[source] = Integer.MAX_VALUE;
        q.offer(source);
        in_q[source] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            in_q[u] = false;
            for (int kb = headList[u]; kb != 0; kb = edgeList.get(kb - 1).nx) {
                Edge e = edgeList.get(kb - 1);
                int v = e.v, w = e.w, c = e.c;
                if (w > 0 && dist[v] > dist[u] + c) {
                    dist[v] = dist[u] + c;
                    flow[v] = Math.min(flow[u], w);
                    pre[v] = u;
                    las[v] = kb;
                    if (!in_q[v]) {
                        q.offer(v);
                        in_q[v] = true;
                    }
                }
            }
        }
        return pre[sink] != 0;
    }

    static int total_flow = 0, total_cost = 0;

    static void computeFlow() {
        while (bellmanFord(sink)) {
            int u = sink;
            int f = flow[sink];
            total_flow += f;
            total_cost += f * dist[sink];
            while (u != source) {
                int kb = las[u];
                Edge e = edgeList.get(kb - 1);
                e.w -= f;
                edgeList.set(kb - 1, e);
                Edge rev = edgeList.get(kb ^ 1);
                rev.w += f;
                edgeList.set(kb ^ 1, rev);
                u = pre[u];
            }
        }
    }

    static void connect(int u, int v, int w, int c) {
        edgeList.add(new Edge(v, w, c, headList[u]));
        headList[u] = edgeList.size();
        edgeList.add(new Edge(u, 0, -c, headList[v]));
        headList[v] = edgeList.size();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int B = Math.max(n, k);
        int maxNode = n * (B * 2 + 1) + 2;
        headList = new int[maxNode];
        Arrays.fill(headList, 0);
        dist = new int[maxNode];
        flow = new int[maxNode];
        pre = new int[maxNode];
        las = new int[maxNode];
        in_q = new boolean[maxNode];

        edgeList.clear();
        edgeCount = 0;

        source = n * (B * 2 + 1) + 1;
        sink = source + 1;

