            int x = sc.nextInt();
            connect(source, x, 1, 0);
        }

        connect(n * (B * 2) + 1, sink, Integer.MAX_VALUE, 0);

        for (int o = 0; o < B * 2; o++) {
            connect(o * n + 1, (o + 1) * n + 1, Integer.MAX_VALUE, 0);
            for (int i = 2; i <= n; i++) {
                connect(o * n + i, (o + 1) * n + i, Integer.MAX_VALUE, c);
            }
        }

        for (int _ = 0; _ < m; _++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int o = 0; o < B * 2; o++) {
                for (int i = 1; i <= k; i++) {
                    int cost = d * (2 * i - 1) + c;
                    connect(o * n + x, (o + 1) * n + y, 1, cost);
                    connect(o * n + y, (o + 1) * n + x, 1, cost);
                }
            }
        }

        computeFlow();
        System.out.println(total_cost);
        sc.close();
    }
}
